# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={365:'Я насупився, мов Люцифер<sup>598</sup>, набрав у груди скільки повітря було в помешканні й сказав:',366:'— Пані нічого нам не винні аж до... жовтня. Саме Стах... тобто пан Вокульський пише мені, що брати триста рублів за три кімнати на цій вулиці — справжній розбій.',367:'Пан Вокульський не може допустити такого здирства й наказав повідомити пань, що від жовтня це помешкання здаватиметься за двісті рублів. А якщо пані не бажають...',368:'Управитель аж відсунувся разом із кріслом. Старенька склала руки, а пані Ставська дивилася на мене великими очима. Ото очі!... Як вона вміє ними дивитися!... Присягаюся, якби я був Вокульським, то освідчився б їй тієї ж миті.',369:'Від її чоловіка, певно, й кісточки не лишилося, якщо він два роки не писав. Зрештою, для чого існують розлучення?... Навіщо Стахові такий маєток?...',370:'Двері знову рипнули, і в них з’явилася дівчинка років дванадцяти, у капелюшку-пастушці<sup>599</sup> й із пачкою зошитів у руці. Дитина мала рум’яне, повне обличчя, але не надто розумний вираз.',371:'Вона вклонилася нам, пані Ставській та її матері, поцілувала маленьку Геленку в обидві щоки й вийшла — мабуть, додому. Потім повернулася з кухні й, зашарівшись аж до очей, спитала пані Ставську:',372:'— Післязавтра о котрій мені прийти?',373:'— Післязавтра, люба... Приходь о четвертій, — відповіла пані Ставська, теж збентежена.',374:'Коли дівчинка нарешті вийшла, мати пані Ставської невдоволеним тоном сказала:',375:'— І це називається уроком, Господи прости... Геленка займається з нею щонайменше півтори години, а за такий урок бере сорок грошів...',376:'— Матусю! — перебила її пані Ставська, благально дивлячись на неї.',377:'(Якби я був Вокульським, то вже повертався б із нею після вінчання. Що за жінка!... які риси... яка гра обличчя. Ніколи в житті не бачив нічого подібного!... А ручка, а постать, зріст, рухи, очі, очі!... )',378:'По хвилі ніякової мовчанки молода пані знову озвалася:',379:'— Ми дуже вдячні панові Вокульському за умови, на яких він залишає нам це помешкання!... Певно, це єдиний випадок, щоб господар сам знижував квартирну плату. Але не знаю, чи... годиться скористатися з його люб’язності?...',380:'— Це не люб’язність, пані, а чесність шляхетної людини! — втрутився управитель. — Пан Вокульський знизив плату і мені, й я погодився... Вулиця, пані, третьорядна, руху мало...',381:'— Зате мешканців знайти легко, — зауважила пані Ставська.',382:'— Ми воліємо давніх, знайомих нам своєю спокійною вдачею й порядком, — сказав я.',383:'— Ви маєте рацію, — похвалила мене сивоволоса пані. — Порядок у помешканні — перше правило, якого ми дотримуємося... Навіть коли Геленка наріже папірців і кине на підлогу, Франуся одразу їх підмітає...',384:'— Та я ж, бабусю, тільки конверти вирізаю, бо пишу листа таткові, щоб він уже повертався, — озвалася дівчинка.'}
ls=open(p,encoding='utf-8').read().splitlines();i=-1;o=[]
for l in ls:
 if l.startswith('**PL:**'):i+=1
 if l=='**UA:**' and i in t:l='**UA:** '+t[i]
 o.append(l)
open(p,'w',encoding='utf-8').write('\n'.join(o));print('filled',len(t))
